//修改描述,可能存在内联源映射
//内联特征
webpackinfo = [`sourceMappingURL`, `webpack_require`, `webpack_exports`, `module = true`, `# sourceURL=webpack:///`]
mirrorNewWebsitePath = func(isHttps /* bool */, url /* string */, req /* []byte */, rsp /* []byte */, body /* []byte */) {
    if file.GetExt(url) == ".js" {
        yakit_output("js文件\n")
        webpack_Features = ""
        for i in webpackinfo {
            if str.Contains(rsp, i) {
                webpack_Features += i+";"//遍历特征                                                    
                yakit_output("发现特征:" + i)
            }
        }
        if webpack_Features != nil {
            map_rsp,_ = poc.Get(url + ".map", poc.https(isHttps))~            
            if str.Contains(map_rsp.BareResponse, "sourceRoot") {
                risk.NewRisk(
                    url, 
                    risk.token("js.map特征已确认"), 
                    risk.title("webpack源码泄露: " + url), 
                    risk.severity("middle"), 
                    risk.details(sprintf("sourceRoot")), 
                    risk.request([]byte("GET " + url + ".map")), 
                    risk.response([]byte(map_rsp.BareResponse)), 
                    risk.description(sprintf("webpack源码泄露")), 
                    risk.solution(`- 在项目路径下修改config/index.js中build对象productionSourceMap: false
- 建议删除或禁止访问正式环境中的js.map文件；`), 
                )
                return
            }

//未能访问到js.map,但是存在内联源映射特征,发出提醒
            risk.NewRisk(
                url, 
                risk.token("webpack"), 
                risk.title(sprintf(
                    "%s未获取到map,可能存在内联源映射,请在浏览器打开", 
                    url, 
                )), 
                risk.severity("info"), 
                risk.details(sprintf(`内联部分特征:` + webpack_Features)), 
                risk.request(req), 
                risk.response(rsp), 
                risk.description(sprintf("疑似webpack源码泄露")), 
                risk.solution(`- 在项目路径下修改config/index.js中build对象productionSourceMap: false
- 建议删除或禁止访问正式环境中的js.map文件；
`), 
            )
        }

    }

}
